import os

TAX_RATES_BY_STATE = {
    'default': 0.08,
    'CA': 0.095,
    'NY': 0.088,
    'TX': 0.0825
}

def get_valid_line_totals(items_list):
    temp_list = []
    for item in items_list:
        is_active = True
        if 'status' in item and item['status'] == 'CANCELLED':
            is_active = False

        if not is_active:
            continue

        try:
            q = int(item.get('qty', '0'))
        except Exception:
            q = 0

        if q > 0:
            item_type = item.get('type')
            if item_type == 'PRODUCT':
                total = item['price'] * q
                temp_list.append(total)
            elif item_type == 'SERVICE':
                total = item['price'] + item.get('fee', 0)
                temp_list.append(total)
    return temp_list

def calculate_final_price(order_data):
    line_totals = get_valid_line_totals(order_data.get('items', []))

    subtotal = 0
    for val in line_totals:
        subtotal += val

    customer_data = order_data.get('customer_info', {})
    customer_level = customer_data.get('level', 'BRONZE')
    discount_percentage = 0.0
    if customer_level == 'GOLD':
        if subtotal > 500:
            discount_percentage = 0.20
        else:
            discount_percentage = 0.15
    elif customer_level == 'SILVER':
        if subtotal > 0:
            discount_percentage = 0.05

    price_after_discount = subtotal * (1 - discount_percentage)

    region = customer_data.get('region', 'default')
    tax_rate = TAX_RATES_BY_STATE.get(region, TAX_RATES_BY_STATE['default'])

    final_total = price_after_discount * (1 + tax_rate)

    return f"${final_total:.2f}"

from datetime import datetime

_g_report_data = {}

def _parse_and_filter(transactions_raw, config_str):
    global _g_report_data
    _g_report_data = {}

    configs = {}
    for part in config_str.split(';'):
        if '=' in part:
            key, val = part.split('=', 1)
            configs[key] = val

    start_date = datetime.strptime(configs['start'], '%Y-%m-%d')
    end_date = datetime.strptime(configs['end'], '%Y-%m-%d')

    filtered_transactions = []
    for trans in transactions_raw:
        if trans.get('user') == 'system_user' or 'date_str' not in trans:
            continue
        try:
            trans_date = datetime.strptime(trans['date_str'], '%Y-%m-%d')
            if start_date <= trans_date <= end_date:
                amount = trans.get('amount', trans.get('amt', 0))
                if isinstance(amount, (int, float)) and amount > 0:
                    filtered_transactions.append({'user': trans['user'], 'amount': amount})
        except Exception:
            pass
    return filtered_transactions, configs.get('rules', '')

def _aggregate_and_calculate(filtered_list, rules_str):
    global _g_report_data
    for item in filtered_list:
        user = item['user']
        if user not in _g_report_data:
            _g_report_data[user] = {'amounts': [], 'total': 0.0}
        _g_report_data[user]['amounts'].append(item['amount'])
        _g_report_data[user]['total'] += item['amount']

    final_report = {}
    raw_rules = rules_str.split(',') if rules_str else []
    for user, data in _g_report_data.items():
        total = data['total']
        count = len(data['amounts'])
        max_val = max(data['amounts']) if data['amounts'] else 0

        discounts = [0.0]
        for rule in raw_rules:
            if ':' in rule and '>' in rule:
                condition, discount_val_str = rule.split(':')
                rule_type, threshold_str = condition.split('>')
                if rule_type == 'total' and total > float(threshold_str):
                    discounts.append(float(discount_val_str))
                elif rule_type == 'count' and count > float(threshold_str):
                    discounts.append(float(discount_val_str))
                elif rule_type == 'max' and max_val > float(threshold_str):
                    discounts.append(float(discount_val_str))

        final_discount = max(discounts)
        final_price = total * (1 - final_discount)

        final_report[user] = {
            'total_spent': round(total, 2),
            'transaction_count': count,
            'average_spend': round(total / count if count else 0, 2),
            'max_transaction': round(max_val, 2),
            'applied_discount_rate': final_discount,
            'final_cost': round(final_price, 2),
            'transactions_sorted_str': ';'.join(map(str, sorted(data['amounts'])))
        }
    return final_report

def process_and_generate_report(transactions, config):
    filtered_data, rules = _parse_and_filter(transactions, config)
    result = _aggregate_and_calculate(filtered_data, rules)
    return result

def merge_user_data(users_db, updates_list):
    result = {}
    for user_id in users_db:
        result[user_id] = {}
        for key in users_db[user_id]:
            result[user_id][key] = users_db[user_id][key]

    for update in updates_list:
        user_id = update.get('id')
        if user_id == None:
            continue
        if user_id not in result:
            result[user_id] = {}
        for field_name in update:
            if field_name != 'id':
                result[user_id][field_name] = update[field_name]

    final_result = {}
    for uid in result:
        if 'name' in result[uid] and 'email' in result[uid]:
            final_result[uid] = result[uid]

    return final_result

def calculate_inventory_value(inventory, price_catalog):
    total_value = 0
    items_processed = 0
    missing_prices = []

    for item_id in inventory:
        quantity = inventory[item_id]
        if type(quantity) == str:
            try:
                quantity = int(quantity)
            except:
                quantity = 0

        if quantity <= 0:
            continue

        price = None
        if item_id in price_catalog:
            price = price_catalog[item_id]

        if price == None:
            missing_prices.append(item_id)
        else:
            item_value = price * quantity
            total_value = total_value + item_value
            items_processed = items_processed + 1

    result_dict = {}
    result_dict['total_value'] = round(total_value, 2)
    result_dict['items_count'] = items_processed
    result_dict['missing_prices'] = missing_prices
    return result_dict

def find_top_customers(orders_list, min_order_value):
    customer_totals = {}

    for order in orders_list:
        customer_id = order.get('customer_id')
        order_total = order.get('total', 0)

        if customer_id not in customer_totals:
            customer_totals[customer_id] = 0
        customer_totals[customer_id] = customer_totals[customer_id] + order_total

    qualified_customers = []
    for cust_id in customer_totals:
        if customer_totals[cust_id] >= min_order_value:
            qualified_customers.append(cust_id)

    sorted_customers = []
    customer_values = []
    for cust_id in qualified_customers:
        customer_values.append((cust_id, customer_totals[cust_id]))

    customer_values.sort(key=lambda x: x[1], reverse=True)

    for item in customer_values:
        sorted_customers.append(item[0])

    return sorted_customers
